// src/seo/ogParams.ts
var MAX_FRACTAL_ITER = 2e3;
var MAX_LYAPUNOV_ITER = 500;
var LYAPUNOV_SEQUENCE = /^[AB]{1,32}$/;
var FRACTAL_RANGES = {
  centerX: { min: -4, max: 4 },
  centerY: { min: -4, max: 4 },
  zoom: { min: 0.01, max: 1e13 },
  cReal: { min: -4, max: 4 },
  cImag: { min: -4, max: 4 },
  p: { min: -4, max: 4 },
  power: { min: 2, max: 12 },
  aMin: { min: 0, max: 4.5 },
  aMax: { min: 0, max: 4.5 },
  bMin: { min: 0, max: 4.5 },
  bMax: { min: 0, max: 4.5 }
};
function parseShareParams(search) {
  const type = search.get("type");
  const meta = type ? getSystemMeta(type) : void 0;
  if (!meta) return null;
  const params = { ...meta.defaultParams };
  for (const key of Object.keys(params)) {
    const raw = search.get(key);
    if (raw === null) continue;
    if (typeof params[key] === "number") {
      const num = parseFloat(raw);
      if (!Number.isFinite(num)) continue;
      const range = meta.paramRanges?.[key] ?? (meta.category === "Fractals" ? FRACTAL_RANGES[key] : void 0);
      params[key] = range ? Math.min(range.max, Math.max(range.min, num)) : num;
    } else if (key === "sequence") {
      if (LYAPUNOV_SEQUENCE.test(raw)) params[key] = raw;
    } else if (typeof params[key] === "string") {
      params[key] = raw;
    }
  }
  if (meta.category === "Fractals" && typeof params.maxIter === "number") {
    const cap = meta.id === "lyapunov" ? MAX_LYAPUNOV_ITER : MAX_FRACTAL_ITER;
    params.maxIter = Math.max(1, Math.min(cap, Math.round(params.maxIter)));
  }
  return { meta, params };
}
function shareQuery({ meta, params }) {
  const q = new URLSearchParams({ type: meta.id });
  for (const [key, value] of Object.entries(params)) q.set(key, String(value));
  return q.toString();
}

// src/seo/site.ts
var SITE_ORIGIN = "https://chaos-iterator.vercel.app";
var SITE_NAME = "Chaos Iterator";
var absolute = (path) => /^https?:\/\//.test(path) ? path : `${SITE_ORIGIN}${path}`;

// src/seo/injectShareMeta.ts
var escapeAttr = (s) => s.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
function setMeta(html, key, name, value) {
  const tag = new RegExp(`<meta\\s[^>]*${key}="${name.replace(/[.:]/g, "\\$&")}"[^>]*>`);
  const content = `content="${escapeAttr(value)}"`;
  if (tag.test(html)) return html.replace(tag, (t) => t.replace(/content="[^"]*"/, content));
  return html.replace("</head>", `<meta ${key}="${name}" ${content} />
</head>`);
}
function shareImageUrl(search) {
  const share = parseShareParams(search);
  return share ? absolute(`/api/og?${shareQuery(share)}`) : null;
}
function injectShareMeta(html, url) {
  const share = parseShareParams(url.searchParams);
  const image = shareImageUrl(url.searchParams);
  if (!share || !image) return null;
  const title = `${share.meta.label} \u2014 ${SITE_NAME}`;
  let out = html;
  out = setMeta(out, "property", "og:image", image);
  out = setMeta(out, "name", "twitter:image", image);
  out = setMeta(out, "property", "og:title", title);
  out = setMeta(out, "name", "twitter:title", title);
  out = setMeta(out, "property", "og:url", url.toString());
  return out;
}

// src/server/proxy.ts
async function proxy(request) {
  const url = new URL(request.url);
  if (!parseShareParams(url.searchParams)) return (0, import_functions.next)();
  try {
    const page = await fetch(new URL("/", url));
    if (!page.ok) return (0, import_functions.next)();
    const html = injectShareMeta(await page.text(), url);
    if (!html) return (0, import_functions.next)();
    return new Response(html, {
      headers: {
        "Content-Type": "text/html; charset=utf-8",
        "Cache-Control": "public, max-age=0, s-maxage=3600"
      }
    });
  } catch {
    return (0, import_functions.next)();
  }
}
